code.cpp:
class Solution {
public:
    long long maximumSumOfHeights(vector<int>& maxHeights) {
        int n = maxHeights.size();
        vector<long long> left(n), right(n);
        stack<int> stk;

        for (int i = 0; i < n; i++) {
            while (!stk.empty() && maxHeights[stk.top()] >= maxHeights[i]) {
                stk.pop();
            }
            if (stk.empty()) {
                left[i] = (long long)maxHeights[i] * (i + 1);
            } else {
                int j = stk.top();
                left[i] = left[j] + (long long)maxHeights[i] * (i - j);
            }
            stk.push(i);
        }

        while (!stk.empty()) stk.pop();

        for (int i = n - 1; i >= 0; i--) {
            while (!stk.empty() && maxHeights[stk.top()] >= maxHeights[i]) {
                stk.pop();
            }
            if (stk.empty()) {
                right[i] = (long long)maxHeights[i] * (n - i);
            } else {
                int j = stk.top();
                right[i] = right[j] + (long long)maxHeights[i] * (j - i);
            }
            stk.push(i);
        }

        long long ans = 0;
        for (int i = 0; i < n; i++) {
            ans = max(ans, left[i] + right[i] - maxHeights[i]);
        }
        return ans;
    }
};
